package local.lito381.server;
import java.util.*;import java.util.function.IntUnaryOperator;import java.nio.file.*;
/** Tests real detached row copies/packets and an executable oracle sliced from frozen Source methods. No Hub/game/SQL. */
public final class SourceCubeTemplatePlan {
 static int cases;static void check(boolean v,String why){if(!v)throw new AssertionError(why);cases++;}
 static final class Draw extends Random implements IntUnaryOperator {int draws;Draw(long seed){super(seed);}public int nextInt(int bound){draws++;return super.nextInt(bound);}public int applyAsInt(int bound){return nextInt(bound);}}
 static NativeDeNpcTemplate row(int id){var row=new NativeDeNpcTemplate();row.set_npcId(id);row.setImpl("L1Effect");row.set_gfxid(5942);row.set_nameid("$1234測試");row.set_level(10);row.set_exp(11);row.set_lawful(-12);row.setLightSize(15);return row;}
 static NativeDeNpcTemplateResources.Snapshot snapshot(Map<Integer,NativeDeNpcTemplate> rows,boolean failure){return new NativeDeNpcTemplateResources.Snapshot("isolated-static-fixture",rows,Map.of(),Map.of(),0,Set.of(),Set.of(),0,0,0,0,0,failure);}
 static int h(byte[]b,int p){return(b[p]&255)|((b[p+1]&255)<<8);}static int d(byte[]b,int p){return h(b,p)|(h(b,p+2)<<16);}
 public static void main(String[]a)throws Exception{
  check(NativeSourceCubeTemplate.freeze(null,80149)==null,"missing snapshot never fabricates template");check(NativeSourceCubeTemplate.freeze(snapshot(Map.of(),false),80149)==null,"missing actual row");var row=row(80149);check(NativeSourceCubeTemplate.freeze(snapshot(Map.of(80149,row),true),80149)==null,"failed original SQL lifecycle is unavailable");row.setImpl("L1Monster");check(NativeSourceCubeTemplate.freeze(snapshot(Map.of(80149,row),false),80149)==null,"actual factory subtype must remain effect");row.setImpl("L1Effect");row.set_npcId(80150);check(NativeSourceCubeTemplate.freeze(snapshot(Map.of(80149,row),false),80149)==null,"map key cannot replace exact template id");row.set_npcId(80149);row.set_randomexp(-1);check(NativeSourceCubeTemplate.freeze(snapshot(Map.of(80149,row),false),80149)==null,"invalid Source random bound before cost");row.set_randomexp(0);row.set_randomlevel(8);check(NativeSourceCubeTemplate.freeze(snapshot(Map.of(80149,row),false),80149)==null,"invalid Source random level bound before cost");row.set_randomlevel(0);
  var template=NativeSourceCubeTemplate.freeze(snapshot(Map.of(80149,row),false),80149);row.set_gfxid(51);row.set_nameid("changed");row.set_exp(999);check(template.gfx()==5942&&template.name().equals("$1234測試")&&template.exp()==11,"original static row frozen, no mutable reload alias");check(Arrays.stream(NativeSourceCubeTemplate.Template.class.getDeclaredFields()).allMatch(f->f.getType().isPrimitive()||f.getType()==String.class),"frozen table data retains neither row nor complete resource snapshot");
  int[] gfxes={51,147,110,57,816,3137,3140,3145,3148,3151,7621,111,998,999,1002,1003,1597,1600,5942,1318,1321,12345};
  for(int gfx:gfxes)for(int mode=0;mode<4;mode++)for(int seed=0;seed<4;seed++){
   int level=mode==3?10:0,exp=mode==0?0:33,lawful=mode<2?0:150;
   var t=new NativeSourceCubeTemplate.Template("isolated-static-fixture",80149,gfx,mode==0?"null":"$1234測試",10,level==0?(mode==2?14:0):level,Integer.MAX_VALUE-5,exp,-50,lawful);var nativeDraw=new Draw(seed);var sourceDraw=new Draw(seed);var actual=NativeSourceCubeTemplate.instantiate(t,nativeDraw);var oracle=new SourceCubeTemplateOracle().evaluate(t,sourceDraw);
   check(actual.gfx()==oracle.gfx&&actual.status()==oracle.status&&actual.exp()==(int)oracle.exp&&actual.lawful()==oracle.lawful&&actual.name().equals(oracle.name)&&nativeDraw.draws==sourceDraw.draws,"executable frozen Source initial presentation and identical draw count/order");
  }
  var fixed=new NativeSourceCubeTemplate.Template("fixture",80149,51,"$999測試",10,0,37,0,-32768,0);var noDraw=new Draw(1);var p=NativeSourceCubeTemplate.instantiate(fixed,noDraw);check(noDraw.draws==0,"fixed Source initial template consumes no RNG");byte[] packet=NativeSourceCubeTemplate.packet(0xf1234567L,32700,32800,p);check((packet[0]&255)==Protocol.S_PUT_OBJECT&&h(packet,1)==32700&&h(packet,3)==32800&&Integer.toUnsignedLong(d(packet,5))==0xf1234567L,"actual native wire object and geometry");check(h(packet,9)==51&&(packet[11]&255)==24&&packet[12]==0&&packet[13]==0&&packet[14]==0,"Source status and zero initial heading/chaLight/move, not template light");check(d(packet,15)==37&&(short)h(packet,19)==-32768,"actual exp and signed tempLawful fields");byte[] name=p.name().getBytes(Protocol.LEGACY_TEXT);check(Arrays.equals(Arrays.copyOfRange(packet,21,21+name.length),name)&&packet[21+name.length]==0&&packet[22+name.length]==0,"native legacy encoding and null title");check((packet[packet.length-7]&255)==255,"retained native hidden HP tail");
  var engine=new BattleCubeIgnitionEffects();var cube=engine.place(1,2,3,4).cube();check(CombatAccess.field(cube,"nativeSourceCubePresentation")==null&&NativeSourceCubeTemplate.packet(cube)==null,"actual unbound native factory keeps original encoder fallback");check(NativeSourceCubeVisibility.matches(Protocol.cubeIgnition(cube),(NativeSourceCubeOrigin.Entity)CombatAccess.field(cube,"nativeSourceCubeEntity"),true),"original unbound encoder still matches original effect identity");check(NativeSourceCubeTemplate.ready(null)==null,"null original preparation remains rejection");
  String source=Files.readString(Path.of(a[0])).replaceAll("\\s+","");String wire=Files.readString(Path.of(a[1])).replaceAll("\\s+","");check(source.contains("this.setLightSize(template.getLightSize())")&&!source.contains("this.setChaLightSize(template.getLightSize())")&&wire.contains("this.writeC(npc.getChaLightSize())"),"fixed Source distinguishes template light from initial wire light");
  if(cases!=371)throw new AssertionError(cases);System.out.println("PASS"+cases+" detached actual template rows, executable frozen Source random/GFX/status/exp/lawful oracle and real native wire/unbound factory cases; no bound cast/role/IO/SQL/Main/game qualification");
 }
}
